hints.code_snippet:
class MagicCrystal {
  _energyStored; 

  constructor(initialEnergy) {
    this._energyStored = Math.max(0, initialEnergy || 0);
  }

  charge(amount) {
    if (amount > 0) {
      this._energyStored += amount;
    }
  }

  drain(amount) {
    if (amount > 0 && this._energyStored >= amount) {
      this._energyStored -= amount;
      return true;
    }
    return false;
  }

  getEnergyLevel() {
    return this._energyStored;
  }
}

